provider "azurerm" {
  features {}
}

variable "location" {
  type = string
  default = "East Asia"
  description = "the default location of the resource"
}

variable "prefix-name" {
  type = string
  description = "The prefix that should attach to all resources"
}

variable "storage_account_kind" {
  type = string
  description = "Kind: BlobStorage, BlockBlobStorage, FileStorage, Storage and StorageV2"
  default = "StorageV2"
}

variable "storage_account_tier" {
  type = string
  description = "Standard and Premium. (BlockBlobStorage and FileStorage accounts only for Premium)"
  default = "Standard"
}

variable "storage_account_account_replication_type" {
  type = string
  description = "Type of replication: LRS, GRS, RA-GRS, ZRS"
  default = "LRS"
}

variable "storage_account_access_tier" {
  type = string
  description = "Access Tier: Hot or Cool"
  default = "Hot"
}

variable "resource_group_name" {
  type = string
  description = "The name of the resource group"
}

variable "os_type" {
  type = string
  description = "The os type of the app service plan"
  default = "Linux"
}

variable "sku_name" {
  type = string
  description = "The sku name of the app service plan"
  default = "Y1"
}

variable "tags" {
  type = map(string)
  description = "The tags for the resources"
  default = {}
}

resource "azurerm_resource_group" "example" {
  name     = var.resource_group_name
  location = var.location
}

resource "azurerm_storage_account" "example" {
  name                     = "${var.prefix-name}-storageaccount"
  resource_group_name      = azurerm_resource_group.example.name
  location                 = azurerm_resource_group.example.location
  account_tier             = var.storage_account_tier
  account_replication_type = var.storage_account_account_replication_type
  account_kind             = var.storage_account_kind
  access_tier              = var.storage_account_access_tier
}

resource "azurecaf_name" "plan_name" {
  name          = var.prefix-name
  resource_type = "azurerm_app_service_plan"
  random_length = 0
  clean_input   = true
}

resource "azurerm_service_plan" "plan" {
  name                = azurecaf_name.plan_name.result
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  os_type             = var.os_type
  sku_name            = var.sku_name

  tags = var.tags
}

resource "azurerm_function_app" "example" {
  name                       = "${var.prefix-name}-functionapp"
  location                   = azurerm_resource_group.example.location
  resource_group_name        = azurerm_resource_group.example.name
  app_service_plan_name       = azurerm_service_plan.plan.name
  app_service_plan_id         = azurerm_service_plan.plan.id
  storage_account_name        = azurerm_storage_account.example.name
  storage_account_access_key  = azurerm_storage_account.example.primary_access_key
  os_type                     = var.os_type
  version                     = "~4"

  site_config {
    linux_fx_version = "DOCKER|mcr.microsoft.com/azure-app-service/samples/node:12-lts"
  }

  tags = var.tags
}

# Configure the Google Cloud Provider
provider "google" {
  version = "~> 4.0"
  region  = var.region
  project = var.project
}

# Variables
variable "region" {
  type        = string
  description = "The region to create the load balancer in"
}

variable "project" {
  type        = string
  description = "The project to create the load balancer in"
}

variable "name" {
  type        = string
  description = "The name of the load balancer"
}

variable "port" {
  type        = number
  description = "The port to use for the load balancer"
}

variable "health_check_port" {
  type        = number
  description = "The port to use for the health check"
}

variable "health_check_path" {
  type        = string
  description = "The path to use for the health check"
}

# Create a backend service
resource "google_compute_backend_service" "default" {
  name        = var.name
  port_name   = "http"
  protocol    = "HTTP"
  timeout_sec = 10

  health_checks = [google_compute_health_check.default.self_link]
}

# Create a health check
resource "google_compute_health_check" "default" {
  name                = "${var.name}-health-check"
  check_interval_sec  = 1
  timeout_sec         = 1
  healthy_threshold   = 1
  unhealthy_threshold = 10

  http_health_check {
    port         = var.health_check_port
    request_path = var.health_check_path
  }
}

# Create a URL map
resource "google_compute_url_map" "default" {
  name            = var.name
  default_service = google_compute_backend_service.default.self_link

  host_rule {
    hosts        = ["*"]
    service      = google_compute_backend_service.default.self_link
  }

  path_matcher {
    name            = "allpaths"
    default_service = google_compute_backend_service.default.self_link

    path_rule {
      paths   = ["/*"]
      service = google_compute_backend_service.default.self_link
    }
  }
}

# Create a target HTTP proxy
resource "google_compute_target_http_proxy" "default" {
  name    = var.name
  url_map = google_compute_url_map.default.self_link
}

# Create a forwarding rule
resource "google_compute_global_forwarding_rule" "default" {
  name       = var.name
  target     = google_compute_target_http_proxy.default.self_link
  port_range = var.port
}

provider "aws" {
  region = var.region
}

resource "aws_kms_key" "s3_kms_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
}

resource "aws_kms_alias" "s3_kms_alias" {
  name          = "alias/s3-kms-key"
  target_key_id = aws_kms_key.s3_kms_key.key_id
}

resource "aws_s3_bucket" "private_bucket" {
  bucket        = var.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "versioning_enabled" {
  bucket = aws_s3_bucket.private_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "kms_encryption" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "block_public_access" {
  bucket = aws_s3_bucket.private_bucket.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

variable "region" {
  type        = string
  description = "AWS region"
}

variable "bucket_name" {
  type        = string
  description = "S3 bucket name"
}

terraform {
  required_version = "~> 1.9"

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.47.0"
    }
    azurecaf = {
      source  = "aztfmod/azurecaf"
      version = "~> 1.2.24"
    }
  }
}

provider "azurerm" {
  features {
    key_vault {
      purge_soft_delete_on_destroy    = true
      recover_soft_deleted_key_vaults = true
    }
  }
}

variable "location" {
  type = string
}

variable "resource_group_name" {
  type = string
}

variable "resource_token" {
  type = string
}

variable "tags" {
  type = map(string)
}

variable "access_policy_object_ids" {
  type = list(string)
}

variable "principal_id" {
  type = string
}

variable "secrets" {
  type = map(string)
}

variable "sp_secret_permissions" {
  type = list(string)
}

resource "azurerm_resource_group" "tftest" {
  name     = var.resource_group_name
  location = var.location
}

resource "azurecaf_name" "kv_name" {
  name          = var.resource_token
  resource_type = "azurerm_key_vault"
  random_length = 0
  clean_input   = true
}

resource "azurerm_key_vault" "kv" {
  name                     = azurecaf_name.kv_name.result
  location                 = azurerm_resource_group.tftest.location
  resource_group_name      = azurerm_resource_group.tftest.name
  tenant_id                = data.azurerm_client_config.current.tenant_id
  purge_protection_enabled = false
  sku_name                 = "standard"

  tags = var.tags
}

data "azurerm_client_config" "current" {}

resource "azurerm_key_vault_access_policy" "app" {
  count        = length(var.access_policy_object_ids)
  key_vault_id = azurerm_key_vault.kv.id
  tenant_id    = data.azurerm_client_config.current.tenant_id
  object_id    = var.access_policy_object_ids[count.index]

  secret_permissions = [
    "Get",
    "Set",
    "List",
    "Delete",
  ]
}

resource "azurerm_key_vault_access_policy" "user" {
  count        = var.principal_id == "" ? 0 : 1
  key_vault_id = azurerm_key_vault.kv.id
  tenant_id    = data.azurerm_client_config.current.tenant_id
  object_id    = var.principal_id

  secret_permissions = [
    "Get",
    "Set",
    "List",
    "Delete",
  ]
}

resource "azurerm_key_vault_access_policy" "sp" {
  key_vault_id = azurerm_key_vault.kv.id
  tenant_id    = data.azurerm_client_config.current.tenant_id
  object_id    = data.azurerm_client_config.current.object_id

  secret_permissions = var.sp_secret_permissions
}

resource "azurerm_key_vault_secret" "keyvault_secrets" {
  depends_on   = [azurerm_key_vault_access_policy.app, azurerm_key_vault_access_policy.user, azurerm_key_vault_access_policy.sp]
  for_each     = var.secrets
  name         = each.key
  value        = each.value
  key_vault_id = azurerm_key_vault.kv.id
}

output "resource_group_name" {
  value = azurerm_resource_group.tftest.name
}

output "resource_group_location" {
  value = azurerm_resource_group.tftest.location
}

output "key_vault_name" {
  value = azurerm_key_vault.kv.name
}

output "key_vault_id" {
  value = azurerm_key_vault.kv.id
}

provider "aws" {
  region = var.region
}

variable "region" {
  type        = string
  description = "AWS Region"
}

variable "role_name" {
  type        = string
  description = "Name of the IAM role"
}

variable "policy_name" {
  type        = string
  description = "Name of the IAM policy"
}

resource "aws_iam_role" "s3_read_access" {
  name        = var.role_name
  description = "Least-privilege role for S3 read access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
        Sid      = ""
      }
    ]
  })
}

resource "aws_iam_policy" "s3_read_access" {
  name        = var.policy_name
  description = "Policy for S3 read access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
        ]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*",
        ]
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_read_access" {
  role       = aws_iam_role.s3_read_access.name
  policy_arn = aws_iam_policy.s3_read_access.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
