resource "azurerm_monitor_autoscale_setting" "example-vmss-as" {
  name = "example-vmss-as"
  resource_group_name = azurerm_resource_group.example.name
  location = azurerm_resource_group.example.location
  target_resource_id = azurerm_virtual_machine_scale_set.example-vmss.id

  profile {
    name = "example-profile"

    capacity {
      default = 2
      minimum = 2
      maximum = 10
    }

    rule {
      metric_trigger {
        metric_name = "Percentage CPU"
        namespace = "microsoft.compute/virtualmachinescalesets"
        resource_id = azurerm_virtual_machine_scale_set.example-vmss.id
        operator = "GreaterThan"
        threshold = 75
      }

      scale_action {
        direction = "Increase"
        type = "ChangeCount"
        value = "1"
        cooldown = "PT5M"
      }
    }

    rule {
      metric_trigger {
        metric_name = "Percentage CPU"
        namespace = "microsoft.compute/virtualmachinescalesets"
        resource_id = azurerm_virtual_machine_scale_set.example-vmss.id
        operator = "LessThan"
        threshold = 25
      }

      scale_action {
        direction = "Decrease"
        type = "ChangeCount"
        value = "1"
        cooldown = "PT5M"
      }
    }
  }
}

