  size                = var.azure_instance_type

  admin_username = "adminuser"
  admin_password = var.azure_admin_password
  disable_password_authentication = false

  network_interface_ids = [
    azurerm_network_interface.example.id,
  ]

  os_disk {
    caching              = "ReadWrite"
