  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "subnet" {
  name          = var.subnet_name
  ip_cidr_range = "10.0.0.0/16"
  network       = google_compute_network.vpc.id
  region        = var.region
}

resource "google_container_cluster" "gke_cluster" {
  provider = google-beta
  name               = "terragoat-${var.environment}-cluster"
  location           = var.region
  initial_node_count = var.node_count

  enable_legacy_abac       = true
  monitoring_service       = "none"
  remove_default_node_pool = true
  network                  = google_compute_network.vpc.name
  subnetwork               = google_compute_subnetwork.subnet.name
  master_authorized_networks_config {
    cidr_blocks {
      cidr_block = "0.0.0.0/0"
    }
  }
}

resource "google_container_node_pool" "node_pool" {
  name       = var.node_pool_name
  location   = var.region
  cluster    = google_container_cluster.gke_cluster.name
  version    = data.google_container_engine_versions.gke_version.release_channel_latest_version["STABLE"]
  node_count = var.node_count

  node_config {
    image_type = var.node_image_type
  }
}

resource "google_compute_network_policy" "network_policy" {
  name = var.network_policy_name
}

resource "google_container_cluster_network_policy" "network_policy_config" {
  provider = google-beta
  cluster  = google_container_cluster.gke_cluster.name
  location = var.region
  policy   = google_compute_network_policy.network_policy.id
}

terraform {
