}

provider "aws" {
  region  = var.aws_region
  profile = var.aws_profile
}

variable "aws_region" {
  type        = string
  description = "AWS region"
}

variable "aws_profile" {
  type        = string
  description = "AWS profile"
}

variable "identifier" {
  type        = string
  description = "Identifier for the resources"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID"
}

variable "subnet_ids" {
  type        = list(string)
  description = "Subnet IDs"
}

variable "security_group_names" {
  type        = list(string)
  description = "Security group names"
}

variable "instance_type" {
  type        = string
  description = "Instance type"
}

variable "mysql_version" {
  type        = string
  description = "MySQL version"
}

variable "allocated_storage" {
  type        = number
  description = "Allocated storage"
}

variable "skip_final_snapshot" {
  type        = bool
  description = "Skip final snapshot"
}

variable "parameters" {
  type        = map(string)
  description = "RDS parameters"
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.identifier}-db-subnet-group"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "${var.identifier} DB subnet group"
  }
}

data "aws_security_group" "security_groups" {
  for_each = toset(var.security_group_names)
  name     = each.value
}

resource "aws_security_group" "allow_mysql" {
  vpc_id = var.vpc_id
  name   = "allow-mysql-${var.identifier}"

  ingress {
    from_port       = 3306
    protocol        = "tcp"
    to_port         = 3306
    security_groups = [for i, g in data.aws_security_group.security_groups : g.id]
  }

  egress {
    from_port       = 0
    protocol        = "-1"
    to_port         = 0
    security_groups = [for i, g in data.aws_security_group.security_groups : g.id]
  }
}

resource "aws_db_parameter_group" "default" {
  family = "mysql8.0"
  name   = "${var.identifier}-parameters"

  dynamic "parameter" {
    for_each = merge(var.parameters, {
      "character_set_server" = "utf8mb4"
      "collation_server"     = "utf8mb4_unicode_ci"
    })
    content {
      name         = parameter.key
      value        = parameter.value
      apply_method = "pending-reboot"
    }
  }
}

resource "aws_db_instance" "default" {
  instance_class                        = var.instance_type
  engine                                = "mysql"
  engine_version                        = var.mysql_version
  allocated_storage                     = var.allocated_storage
  max_allocated_storage                 = 60
  skip_final_snapshot                   = var.skip_final_snapshot
  identifier                            = var.identifier
  db_subnet_group_name                  = aws_db_subnet_group.default.name
  parameter_group_name                  = aws_db_parameter_group.default.name
  vpc_security_group_ids                = [aws_security_group.allow_mysql.id]
  publicly_accessible                   = false
  deletion_protection                   = false
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = ">= 3.0, < 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "location" {
  type = string
}

variable "cosmosdb_account_name" {
  type    = string
  default = null
}

variable "cosmosdb_account_location" {
  type    = string
  default = null
}

variable "cosmosdb_sqldb_name" {
  type = string
}

variable "cosmosdb_container_name" {
  type = string
}

variable "cosmosdb_container_partition_key_path" {
  type = string
}

resource "azurerm_resource_group" "example" {
  name     = "${random_pet.prefix.id}-rg"
  location = var.location
}

resource "random_pet" "prefix" {
  length = 5
}

resource "random_string" "db_account_name" {
  count = var.cosmosdb_account_name == null ? 1 : 0

  length  = 20
  upper   = false
  special = false
  numeric = false
}

locals {
  cosmosdb_account_name = try(random_string.db_account_name[0].result, var.cosmosdb_account_name)
}

resource "azurerm_cosmosdb_account" "example" {
  name                      = local.cosmosdb_account_name
  location                  = var.cosmosdb_account_location != null ? var.cosmosdb_account_location : var.location
  resource_group_name       = azurerm_resource_group.example.name
  offer_type                = "Standard"
  kind                      = "GlobalDocumentDB"
  enable_automatic_failover = false
  geo_location {
    location          = var.location
    failover_priority = 0
  }
  consistency_policy {
    consistency_level       = "BoundedStaleness"
    max_interval_in_seconds = 300
    max_staleness_prefix    = 100000
  }
  depends_on = [
    azurerm_resource_group.example
  ]
}

resource "azurerm_cosmosdb_sql_database" "main" {
  name                = var.cosmosdb_sqldb_name
  resource_group_name = azurerm_resource_group.example.name
  account_name        = azurerm_cosmosdb_account.example.name
}

resource "azurerm_cosmosdb_sql_container" "example" {
  name                  = var.cosmosdb_container_name
  resource_group_name   = azurerm_resource_group.example.name
  account_name          = azurerm_cosmosdb_account.example.name
  database_name         = azurerm_cosmosdb_sql_database.main.name
  partition_key_path    = var.cosmosdb_container_partition_key_path
  partition_key_version = 1
  throughput            = 400
}

output "cosmosdb_account_name" {
  value = azurerm_cosmosdb_account.example.name
}

output "cosmosdb_account_key" {
  value     = azurerm_cosmosdb_account.example.primary_key
  sensitive = true
}

output "cosmosdb_sql_database_name" {
  value = azurerm_cosmosdb_sql_database.main.name
}

output "cosmosdb_sql_container_name" {
  value = azurerm_cosmosdb_sql_container.example.name
}

