  cidr_block        = var.subnet2_cidr_block
  availability_zone = var.availability_zone2
  tags = {
    Name = "example-subnet2"
  }
}

# Create security group for the ALB
resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for the ALB"
  vpc_id      = aws_vpc.example.id

  ingress {
    description = "Allow HTTP traffic"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

# Create the ALB
resource "aws_lb" "example" {
  name               = "example-alb"
  load_balancer_type = "application"
  subnets            = [aws_subnet.example1.id, aws_subnet.example2.id]
  security_groups    = [aws_security_group.alb_sg.id]
  enable_deletion_protection = false
  tags = {
    Environment = "example-alb"
  }
}

# Create target groups
resource "aws_lb_target_group" "example1" {
  name     = "example-tg1"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    healthy_threshold   = 2
    interval            = 30
    matcher             = "200"
    path                = "/healthz/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 20
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-tg1"
  }
}

resource "aws_lb_target_group" "example2" {
  name     = "example-tg2"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    healthy_threshold   = 2
    interval            = 30
    matcher             = "200"
    path                = "/healthz/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 20
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-tg2"
  }
}

# Create listener
resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_lb_target_group.example1.arn
    type             = "forward"
  }
}

# Create listener rules
resource "aws_lb_listener_rule" "example1" {
  listener_arn = aws_lb_listener.example.arn
  priority     = 1

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example1.arn
  }

  condition {
    path_pattern {
      values = ["/path1/*"]
    }
  }
}

resource "aws_lb_listener_rule" "example2" {
  listener_arn = aws_lb_listener.example.arn
  priority     = 2

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example2.arn
  }

  condition {
    path_pattern {
      values = ["/path2/*"]
    }
  }
}

