      retention_policy {
        days    = log.value ? var.diagsettings_retention_days : 0
        enabled = log.value
      }
    }
  }

  dynamic "metric" {
    for_each = var.diagsettings_metric_category
    content {
      category = metric.key
      enabled  = metric.value

      retention_policy {
        days    = metric.value ? var.diagsettings_retention_days : 0
        enabled = metric.value
      }
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Create an IAM role for the AWS Lambda function
resource "aws_iam_role" "lambda_exec" {
  name        = "serverless_example_lambda"
  description = "Execution role for AWS Lambda"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid      = ""
      }
    ]
  })
}

# Create an IAM policy for the AWS Lambda function
resource "aws_iam_policy" "lambda_policy" {
  name        = "serverless_example_lambda_policy"
  description = "Policy for AWS Lambda execution role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Create a CloudWatch log group for the AWS Lambda function
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/serverless_example"
  retention_in_days = 14
}

# Create the AWS Lambda function
resource "aws_lambda_function" "example" {
  filename      = "lambda_function_payload.zip"
  function_name = "serverless_example"
  handler       = "index.handler"
  runtime       = "nodejs16.x"
  role          = aws_iam_role.lambda_exec.arn
}

