  filename      = "lambda_function_payload.zip"
  function_name = var.function_name
  handler       = var.handler
  runtime       = var.runtime
  role          = aws_iam_role.lambda_exec.arn

  s3_bucket = var.bucket_name
  s3_key    = var.s3_key
}

