  description = "Allow HTTPS inbound traffic, block SSH"
  vpc_id      = var.vpc_id

  ingress {
    description = "HTTPS inbound traffic"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.https_cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.egress_cidr_blocks
  }

  tags = {
    Name = "HTTPS Security Group"
  }
}

