  dataset_id = google_bigquery_dataset.dataset.dataset_id
  table_id   = var.table_name

  schema = jsonencode([
    {
      name = "id"
      type = "INTEGER"
      mode = "NULLABLE"
    },
    {
      name = "name"
      type = "STRING"
      mode = "NULLABLE"
    }
  ])

  clustering = [
    {
      field = "id"
    }
  ]

  expiration_time = timeadd(timestamp(), "1h")

  labels = {
    env = "dev"
  }
}

